export const GLOSSARY_SHARD = Object.freeze({"ethereum":{"slug":"ethereum","cat":"basics","en":"Ethereum (ETH)","contentLocale":"en","term":"Ethereum (ETH)","aka":["ETH","Ether"],"short":"Ethereum is a programmable blockchain that runs smart contracts, and Ether (ETH) is its native coin used to pay gas fees and to stake for network security.","body":[["Where ",["Bitcoin","bitcoin"]," focuses on being money, Ethereum is designed as a global computer. Developers deploy smart contracts, programs that run exactly as written, and these power ",["stablecoins","stablecoin"],", decentralized exchanges, lending markets, ",["NFTs","nft"]," and many of the tokens you see on exchanges."],["Every action on Ethereum costs gas, paid in ETH. When the network is busy, gas prices rise, which is why many users move to ",["layer 2","layer-2"]," networks such as Arbitrum, Optimism or Base that settle back to Ethereum but charge much lower fees. Since 2021, part of every fee is burned, permanently removing that ETH from supply."],["In September 2022 Ethereum moved from ",["proof of work","proof-of-work"]," to ",["proof of stake","proof-of-stake"]," in an upgrade called the Merge. Validators now lock up ETH to propose and confirm blocks and earn rewards for doing so. Many exchanges let you stake ETH through their earn products, while liquid staking protocols give you a token that represents staked ETH. Check the lock-up and withdrawal terms before you stake."]],"example":"Suppose you want to swap tokens on a decentralized exchange on Ethereum mainnet and the gas cost is 150,000 units at 20 gwei. The fee is 150,000 x 20 = 3,000,000 gwei, or 0.003 ETH. At an ETH price of 3,000 USDT, that is about 9 USDT. The same swap on a layer 2 might cost well under 0.10 USDT, which matters a lot if you are only trading 50 USDT.","mistakes":["Withdrawing ETH to a layer 2 or another EVM chain without checking which network the receiving wallet or exchange supports.","Keeping no ETH in a wallet, then being unable to move ERC20 tokens because there is nothing to pay gas with.","Assuming staked ETH can always be withdrawn instantly; unstaking can involve a queue or product-specific lock period."],"faq":[{"q":"Is Ether the same as Ethereum?","a":"Ethereum is the network, and Ether (ETH) is its native coin. In everyday speech many people call the coin Ethereum too."},{"q":"Does Ethereum have a maximum supply?","a":"No fixed cap exists. New ETH is issued to validators, while part of every transaction fee is burned, so net supply can rise or fall depending on network activity."},{"q":"What changed with the Merge?","a":"In September 2022 Ethereum switched from proof of work to proof of stake. Mining ended, and validators who stake ETH now secure the network."}],"title":"What is Ethereum (ETH)? Meaning, gas and staking","description":"Learn what Ethereum and Ether are, how gas fees are calculated, and what the Merge and proof of stake changed.","related":[["smart-contract","Smart contract","A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman."],["gas-fee","Gas fee","A gas fee is the payment you make to a blockchain network to process a transaction or run a smart contract, paid in the chain's native coin such as ETH on Ethereum."],["proof-of-stake","Proof of stake (PoS)","Proof of stake (PoS) is a consensus mechanism in which validators lock up the network's coins as collateral to propose and confirm blocks, earning rewards for honest work and losing part of their stake for breaking the rules."],["layer-2","Layer 2 (L2)","A layer 2 (L2) is a network built on top of a layer 1 blockchain that processes transactions off the main chain and posts the results back to it, giving lower fees while borrowing much of the L1's security."],["defi","DeFi (decentralized finance)","DeFi, short for decentralized finance, is a set of financial services such as trading, lending and earning yield that run on public blockchains through smart contracts instead of through banks or exchanges."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":true},"layer-1":{"slug":"layer-1","cat":"basics","en":"Layer 1 (L1)","contentLocale":"en","term":"Layer 1 (L1)","aka":["L1","base layer","layer one"],"short":"A layer 1 (L1) is a base blockchain that processes and finalises transactions on its own network with its own consensus and native coin, such as Bitcoin, Ethereum or Solana.","body":[["An L1 is responsible for everything: ordering transactions, reaching consensus, storing data and securing the chain. It has its own ",["native coin","coin-vs-token"]," used for fees and, on proof-of-stake chains, for ",["staking","staking"],". ",["Bitcoin","bitcoin"],", ",["Ethereum","ethereum"],", Solana, BNB Chain, Avalanche and Tron are all layer 1 networks."],["L1 designs trade off three goals: security, decentralization and scalability. Ethereum keeps its base layer conservative and pushes most activity to ",["layer 2","layer-2"]," networks. Solana aims for high throughput on the L1 itself, with more demanding hardware for validators. Neither choice is free; each shapes fees, speed and how many people can run a ",["node","node"],"."],"For you, the L1 decides which wallet format you use, which coin pays gas and how long withdrawals take. When an exchange lists withdrawal networks for a token, many of those options are different L1s, each with its own fee and confirmation time."],"example":"Suppose you want to send 100 USDT to a friend. On an exchange you might see options such as Ethereum, Tron and Solana, all of which are layer 1 networks. The exchange might charge a few USDT for the Ethereum route because base-layer gas is expensive, and well under 1 USDT for Solana. If your friend's wallet only supports Tron, you must pick Tron, even if another network is cheaper, or the funds may not arrive.","mistakes":["Assuming the same address works on every L1; formats and supported tokens differ.","Choosing the cheapest withdrawal network without checking that the receiver supports it.","Judging an L1 only by transaction speed while ignoring decentralization and security."],"faq":[{"q":"What is the difference between layer 1 and layer 2?","a":"A layer 1 settles transactions on its own chain. A layer 2 processes transactions separately and posts proofs or data back to a layer 1, inheriting much of its security."},{"q":"Is Bitcoin a layer 1?","a":"Yes. Bitcoin is the original layer 1. Systems such as the Lightning Network are built on top of it."},{"q":"Why are there so many layer 1 blockchains?","a":"Teams make different design choices for speed, cost, programming languages and decentralization, and each L1 competes for users and developers."}],"title":"What is a layer 1 (L1) blockchain? Meaning","description":"Learn what a layer 1 blockchain is, how L1s differ from layer 2s and why the network matters for your transfers.","related":[["layer-2","Layer 2 (L2)","A layer 2 (L2) is a network built on top of a layer 1 blockchain that processes transactions off the main chain and posts the results back to it, giving lower fees while borrowing much of the L1's security."],["blockchain","Blockchain","A blockchain is a shared digital ledger, copied across many computers, where transactions are grouped into blocks that are linked in order and are extremely hard to change after the fact."],["ethereum","Ethereum (ETH)","Ethereum is a programmable blockchain that runs smart contracts, and Ether (ETH) is its native coin used to pay gas fees and to stake for network security."],["gas-fee","Gas fee","A gas fee is the payment you make to a blockchain network to process a transaction or run a smart contract, paid in the chain's native coin such as ETH on Ethereum."],["coin-vs-token","Coin vs token","A coin is the native asset of its own blockchain, such as BTC or ETH, while a token is an asset created on top of an existing blockchain using a smart contract, such as USDT on Ethereum."]],"lesson":null,"coin":{"slug":"solana","name":"Solana","symbol":"SOL"},"tool":null,"cta":false},"token-burn":{"slug":"token-burn","cat":"basics","en":"Token burn","contentLocale":"en","term":"Token burn","aka":["coin burn","burn","buyback and burn"],"short":"A token burn is the permanent removal of tokens from circulation by sending them to an address that nobody can access or by destroying them through a smart contract.","body":[["Burned tokens still exist on the ",["blockchain","blockchain"]," in a technical sense, but no one holds a key to spend them. Common burn addresses are made of zeros or follow a known pattern, so anyone can verify the balance on a ",["block explorer","block-explorer"],"."],["Projects burn tokens for different reasons. Some burn part of every ",["transaction fee","gas-fee"],", as ",["Ethereum","ethereum"]," has done with its base fee since 2021. Others use revenue to buy tokens on the market and burn them, as BNB does with its periodic burn program. Some burn unsold tokens after a sale."],"A burn reduces supply, but it does not by itself create demand. If a project burns 1 percent of supply while unlocking 5 percent, net supply still grows. Check how burns are funded, whether they are automatic or discretionary, and how they compare with new issuance."],"example":["Suppose a token has 500 million in circulation. In a quarter, the project spends 2 million ",["USDT","usdt"]," of revenue buying tokens at an average of 0.40 USDT, receiving 5 million tokens, and burns them. ",["Circulating supply","circulating-supply"]," drops to 495 million, a 1 percent reduction. In the same quarter, 12.5 million new tokens unlock for the team. Net supply therefore still rises by 7.5 million tokens, or 1.5 percent."],"mistakes":["Assuming any burn announcement means the price will rise.","Not checking whether burns are larger or smaller than new token issuance and unlocks.","Believing a project's burn claim without verifying the burn address on a block explorer."],"faq":[{"q":"Why do crypto projects burn tokens?","a":"To reduce supply, offset issuance, share revenue with holders indirectly or remove unsold tokens. The effect depends on how much is burned relative to new supply and demand."},{"q":"Can burned tokens be recovered?","a":"No, if they were sent to a true burn address or destroyed by a contract, no one can access them again."},{"q":"Is ETH burned?","a":"Yes. Since 2021, the base fee portion of every Ethereum transaction fee is burned."}],"title":"What is a token burn? Meaning in crypto","description":"Learn what a token burn is, why projects burn coins, and how to compare burns with new issuance.","related":[["tokenomics","Tokenomics","Tokenomics is the economic design of a cryptocurrency, covering how many tokens exist, who received them, how new tokens are released and what the token is actually used for."],["circulating-supply","Circulating supply","Circulating supply is the number of coins or tokens that are publicly available and moving in the market right now, excluding locked, reserved or burned tokens."],["market-capitalization","Market capitalization","Market capitalization is the total value of a cryptocurrency's circulating coins, calculated as the current price multiplied by the circulating supply."],["coin-vs-token","Coin vs token","A coin is the native asset of its own blockchain, such as BTC or ETH, while a token is an asset created on top of an existing blockchain using a smart contract, such as USDT on Ethereum."]],"lesson":null,"coin":{"slug":"bnb","name":"BNB","symbol":"BNB"},"tool":null,"cta":false},"fud":{"slug":"fud","cat":"basics","en":"FUD","contentLocale":"en","term":"FUD","aka":["fear, uncertainty and doubt"],"short":"FUD, short for fear, uncertainty and doubt, describes negative news, rumours or opinions that make people worried about an asset, whether the concerns are valid or not.","body":["In crypto, FUD can be a genuine warning, such as reports that an exchange has delayed withdrawals, or a misleading rumour spread to push prices down. People also label any criticism of their favourite coin as FUD, which can make them ignore real problems.","The skill is separating noise from signal. Ask where the claim comes from, whether it is backed by data you can check, and whether primary sources confirm it. Exchange announcements, on-chain wallet flows, regulatory filings and official project statements are stronger than anonymous posts.","FUD often triggers quick, emotional selling. If a claim turns out to be false, prices can recover just as fast. If it is true, waiting too long can be costly. Having a plan for what would make you exit, decided before the news, helps you react calmly either way."],"example":["Suppose a rumour spreads that a token's team wallet is dumping, and the price falls from 2.00 to 1.70 ",["USDT","usdt"]," in an hour, down 15 percent. You check a ",["block explorer","block-explorer"]," and see that the team wallet moved 5 million tokens to a ",["staking","staking"]," ",["contract","smart-contract"],", not to an exchange. Within a day the price recovers to 1.95. In another case, if you had seen those 5 million tokens arrive at an exchange ",["deposit address","wallet-address"],", the concern would have had real evidence behind it."],"mistakes":["Panic-selling on an unverified post without checking primary sources.","Dismissing every critical report as FUD, including real warnings about a platform's solvency.","Trusting screenshots of supposed exchange messages that could be edited."],"faq":[{"q":"What does FUD mean in crypto?","a":"FUD stands for fear, uncertainty and doubt. It refers to negative information or rumours that can push people to sell."},{"q":"Is all FUD false?","a":"No. Some FUD is misleading, but some is a real warning. Check the evidence before deciding."},{"q":"How can I verify crypto FUD?","a":"Look for official announcements, regulatory documents and on-chain data such as wallet movements on a block explorer."}],"title":"What does FUD mean in crypto? Meaning explained","description":"Learn what FUD means in crypto, how to tell real warnings from rumours and what evidence to check before reacting.","related":[["fomo","FOMO","FOMO, or fear of missing out, is the anxious urge to buy an asset after its price has already risen sharply, driven by the worry that others are profiting without you."],["bear-market","Bear market","A bear market is a sustained period of falling prices and pessimistic sentiment, commonly described as a decline of 20 percent or more from a recent high."],["fear-and-greed-index","Fear and Greed Index","The Fear and Greed Index is a sentiment gauge that combines market data such as volatility, momentum and social activity into a single score from 0 (extreme fear) to 100 (extreme greed)."],["on-chain-analysis","On-chain analysis","On-chain analysis is the study of public blockchain data, such as transactions, wallet balances and exchange flows, to understand how a network is used and how holders behave."]],"lesson":{"id":"E11","slug":"scam-red-flags","ep":11,"title":"Someone says he can make you money. First, see what he wants."},"coin":null,"tool":null,"cta":false},"bid-ask-spread":{"slug":"bid-ask-spread","cat":"trading","en":"Bid-ask spread","contentLocale":"en","term":"Bid-ask spread","aka":["spread","bid/ask spread","bid-offer spread"],"short":"The bid-ask spread is the difference between the highest price a buyer is willing to pay (the bid) and the lowest price a seller is willing to accept (the ask) for an asset at a given moment.","body":[["If the best bid for a coin is 99.90 ",["USDT","usdt"]," and the best ask is 100.10, the spread is 0.20 USDT, or about 0.2 percent of the price. When you buy with a ",["market order","market-order"]," you pay the ask; when you sell you receive the bid. A round trip with market orders therefore costs you the spread on top of trading fees."],["Spreads are tight on liquid pairs such as ",["BTC","bitcoin"],"/USDT on major exchanges, often just one tick wide. They widen on small coins, during fast-moving news, in quiet hours and on platforms with little ",["liquidity","liquidity"],". Market makers earn part of their income by quoting both sides and capturing the spread."],["Instant buy or ",["convert","instant-convert"]," screens often hide the spread inside the quoted price instead of showing a separate fee. Compare that price with the ",["order book","order-book"]," mid price to see what you are really paying. Using limit orders lets you avoid crossing the spread, at the risk that your order is not filled."]],"example":"Suppose a small altcoin shows a best bid of 0.4950 and a best ask of 0.5050 USDT. The spread is 0.0100, which is 2 percent of the 0.50 mid price. If you buy 1,000 USDT worth at the ask and immediately sell at the bid, you would get back about 980 USDT before fees, a 20 USDT loss from the spread alone. On BTC/USDT the same round trip might cost a few cents.","mistakes":["Ignoring the spread and counting only the trading fee as your cost.","Using an instant buy screen without comparing its price with the order book.","Trading illiquid coins with market orders during volatile news when spreads widen."],"faq":[{"q":"What is a good bid-ask spread?","a":"On highly liquid pairs it can be a tiny fraction of a percent. On small coins, spreads of 0.5 to 2 percent or more are common, which makes frequent trading expensive."},{"q":"Why does the spread widen?","a":"Spreads widen when liquidity is thin, volatility is high or market makers pull their quotes, for example around major news."},{"q":"How can I avoid paying the spread?","a":"Use limit orders at your chosen price instead of market orders, accepting that your order may not fill."}],"title":"What is the bid-ask spread in crypto? Meaning","description":"Learn what the bid-ask spread is, how it adds to your trading costs and why it widens on small coins and during news.","related":[["order-book","Order book","An order book is the live list of all open buy orders (bids) and sell orders (asks) for a trading pair, sorted by price, showing how much people are willing to trade at each level."],["slippage","Slippage","Slippage is the difference between the price you expect when you place a trade and the average price at which the trade actually fills, usually caused by thin liquidity or fast-moving markets."],["liquidity","Liquidity","Liquidity is how easily you can buy or sell an asset quickly, in size, without moving its price much."],["market-maker","Market maker","A market maker is a trader or firm that continuously places both buy and sell orders on a market, providing liquidity and earning from the spread between them."],["maker-taker-fees","Maker and taker fees","Maker and taker fees are the two trading fee rates an exchange charges: a maker fee when your order adds liquidity to the order book, and a usually higher taker fee when your order removes it."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Why isn't the price on screen my fill price?"},"coin":null,"tool":"/rates","cta":false},"slippage":{"slug":"slippage","cat":"trading","en":"Slippage","contentLocale":"en","term":"Slippage","aka":["price slippage","slippage tolerance"],"short":"Slippage is the difference between the price you expect when you place a trade and the average price at which the trade actually fills, usually caused by thin liquidity or fast-moving markets.","body":[["On a ",["centralized exchange","centralized-exchange"],", slippage happens when your ",["market order","market-order"]," is larger than the size available at the best price, so it fills across several price levels in the ",["order book","order-book"],". It also happens when the price moves between the moment you click and the moment your order arrives."],["On decentralized exchanges using ",["liquidity","liquidity"]," pools, every trade moves the price along a curve. The bigger your trade relative to the pool, the worse your average price, which is called price impact. ",["DEX","dex"]," interfaces let you set a slippage tolerance; if the final price is worse than that limit, the transaction fails instead of filling."],"Slippage can work in your favour, but in practice it usually costs money on market orders. To reduce it, trade liquid pairs, split large orders, use limit orders and avoid trading in the seconds after major news. On DEXs, a very high slippage tolerance can make you an easy target for front-running bots."],"example":["Suppose you want to buy 5,000 ",["USDT","usdt"]," of a token showing a price of 2.00 USDT. On a thin pool, your trade pushes the price up, and you receive 2,450 tokens instead of the expected 2,500. Your average price is about 2.041, so slippage was roughly 2 percent, costing about 100 USDT. Splitting the order into five 1,000 USDT trades spaced out over time could reduce the impact if liquidity refills between them."],"mistakes":["Setting slippage tolerance to 10 percent or more on a DEX without understanding why a trade failed.","Placing one large market order in a thin order book instead of splitting it or using limit orders.","Blaming the exchange for slippage that came from your own order size."],"faq":[{"q":"What is a good slippage tolerance?","a":"For liquid pairs, many traders use around 0.5 percent or less. Volatile or low-liquidity tokens may need more, but a high setting increases the risk of a bad fill."},{"q":"Is slippage a fee?","a":"No. Slippage is not charged by the exchange; it is the difference in price caused by liquidity and market movement."},{"q":"Can slippage be positive?","a":"Yes. If the price moves in your favour before your order fills, you can get a better price than expected."}],"title":"What is slippage in crypto? Meaning and how to reduce it","description":"Learn what slippage is, why it happens on exchanges and DEXs and practical ways to reduce it on large trades.","related":[["bid-ask-spread","Bid-ask spread","The bid-ask spread is the difference between the highest price a buyer is willing to pay (the bid) and the lowest price a seller is willing to accept (the ask) for an asset at a given moment."],["market-order","Market order","A market order is an instruction to buy or sell immediately at the best price currently available in the order book, prioritising speed of execution over a specific price."],["liquidity","Liquidity","Liquidity is how easily you can buy or sell an asset quickly, in size, without moving its price much."],["order-book","Order book","An order book is the live list of all open buy orders (bids) and sell orders (asks) for a trading pair, sorted by price, showing how much people are willing to trade at each level."],["amm","Automated market maker (AMM)","An automated market maker (AMM) is a type of DEX that prices trades with a mathematical formula based on the tokens held in a liquidity pool, instead of matching buyers and sellers in an order book."]],"lesson":{"id":"E13","slug":"price-vs-fill-price","ep":13,"title":"Why isn't the price on screen my fill price?"},"coin":null,"tool":"/rates","cta":false},"trailing-stop":{"slug":"trailing-stop","cat":"trading","en":"Trailing stop","contentLocale":"en","term":"Trailing stop","aka":["trailing stop-loss","trailing stop order"],"short":"A trailing stop is a stop order that automatically follows the price at a set distance as it moves in your favour, then triggers if the price reverses by that distance.","body":[["You set a callback rate, such as 5 percent, or a fixed price distance. For a long position, the stop rises as the price makes new highs but never moves down. If the price then falls 5 percent from its highest point since activation, the order triggers and closes the position, usually with a ",["market order","market-order"],"."],"Trailing stops let you protect profits in a trend without guessing the top. They work best in strong directional moves. In choppy markets, a tight trailing distance can stop you out on normal swings before the trend continues.",["Many exchanges let you set an activation price, so the trailing only starts once the trade is already in profit. Settings vary between platforms, for example whether the callback uses ",["last price","last-price"]," or ",["mark price","mark-price"],", so read the order details on your exchange before relying on it."]],"example":["Suppose you buy a coin at 40 ",["USDT","usdt"]," and set a trailing stop with a 10 percent callback. The price climbs to 50, so the stop moves up to 45. It then rises to 56, moving the stop to 50.40. The price then drops, and when it reaches 50.40 the order triggers. You exit with a gain of about 10.40 USDT per coin, roughly 26 percent, even though you did not sell at the 56 top."],"mistakes":["Setting a callback rate smaller than the coin's normal daily swings.","Expecting the trailing stop to move down again if the price falls; it only ratchets in your favour.","Not checking whether the order triggers on last price or mark price on futures."],"faq":[{"q":"What is a good trailing stop percentage?","a":"It should be wider than the coin's normal pullbacks. Large coins may suit a few percent, while volatile altcoins may need 10 percent or more."},{"q":"Does a trailing stop guarantee my exit price?","a":"No. It usually triggers a market order, so the fill can be slightly worse than the trigger in fast markets."},{"q":"What is an activation price in a trailing stop?","a":"It is the price at which the trailing begins. Before that price is reached, the order is inactive."}],"title":"What is a trailing stop? Meaning and example","description":"Learn how a trailing stop follows the price, how the callback rate works and how to avoid being stopped out by noise.","related":[["stop-loss","Stop-loss order","A stop-loss order is an order that automatically closes your position when the price reaches a level you set, limiting how much you can lose on a trade."],["take-profit","Take-profit order","A take-profit order is an order that automatically closes all or part of your position when the price reaches a target level, locking in gains without you having to watch the market."],["stop-limit-order","Stop-limit order","A stop-limit order combines a stop price and a limit price: when the market reaches the stop price, a limit order is placed at your limit price, so it only fills at that price or better."],["volatility","Volatility","Volatility is a measure of how much and how quickly an asset's price moves up and down over a given period, and higher volatility means larger, faster swings."]],"lesson":{"id":"E17","slug":"stop-loss-is-a-plan","ep":17,"title":"Take-profit and stop-loss are plans, not insurance"},"coin":null,"tool":null,"cta":false},"mark-price":{"slug":"mark-price","cat":"derivatives","en":"Mark price","contentLocale":"en","term":"Mark price","aka":["fair price","marking price"],"short":"The mark price is a fair-value price an exchange uses to calculate unrealized profit and loss and to trigger liquidations, instead of the last traded price.","body":[["The ",["last traded price","last-price"]," on a single futures ",["order book","order-book"]," can spike for a moment because of one large order or thin ",["liquidity","liquidity"],". If liquidations used that price, traders could be wiped out by a wick that lasts a second. The mark price smooths this out."],["Exchanges typically build the mark price from the ",["index price","index-price"],", an average of spot prices across several major exchanges, plus a smoothed measure of the ",["futures premium","futures-basis"]," or basis. Some use a median of several inputs. The exact formula differs by exchange and is published in its documentation."],["In practice, your ",["unrealized PnL","unrealized-pnl"],", margin ratio and liquidation are based on the mark price. Many platforms let you choose whether a stop-loss triggers on the mark price or the last price. The two are usually close, but in volatile moments they can differ, which explains many surprises about when a position closed."]],"example":"Suppose a perpetual's last price briefly drops from 2,500 to 2,380 USDT when a large market sell hits a thin order book, while spot prices on other exchanges stay near 2,495. The mark price, anchored to the index, only dips to about 2,492. A long with a liquidation price of 2,400 survives, because the mark price never reached it, even though the chart shows a wick to 2,380.","mistakes":["Watching only the candlestick chart, which shows the last price, to judge liquidation risk.","Not checking whether stop-loss orders trigger on the mark price or the last price.","Assuming the mark price is the same on every exchange."],"faq":[{"q":"What is the difference between mark price and last price?","a":"Last price is the latest trade on that order book. Mark price is a smoothed fair value based mainly on the index, used for PnL and liquidation."},{"q":"Why do exchanges use mark price for liquidation?","a":"To stop brief price spikes or manipulation on one order book from causing unfair liquidations."}],"title":"What is mark price in crypto futures? Explained","description":"Learn what mark price is, how exchanges calculate it, and why it decides your liquidation instead of the last traded price.","related":[["index-price","Index price","The index price is a reference price for an asset calculated from a weighted average of spot prices on several major exchanges, used to anchor futures pricing."],["liquidation-price","Liquidation price","The liquidation price is the mark price at which your leveraged position will be forcibly closed because your margin would fall to the maintenance margin level."],["last-price","Last traded price","The last traded price is the price at which the most recent trade on an order book was executed, and it is the price you usually see on charts and tickers."],["funding-rate","Funding rate","A funding rate is a periodic payment between long and short traders that keeps a perpetual futures price close to the spot price."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Liquidation: who pressed the forced-close button?"},"coin":null,"tool":"/funding-rates","cta":false},"instant-convert":{"slug":"instant-convert","cat":"exchange-features","en":"Convert (instant swap)","contentLocale":"en","term":"Convert (instant swap)","aka":["convert","instant swap","quick buy","flash swap"],"short":"Convert is an exchange feature that swaps one coin for another at a quoted price in one click, without using the order book directly.","body":[["When you use Convert, the exchange shows a quote such as 1 ",["ETH","ethereum"]," for 3,000 ",["USDT","usdt"],", valid for a few seconds. If you accept, the swap executes at exactly that rate. You do not choose between maker or taker orders or worry about partial fills."],["Many exchanges advertise Convert as zero fee, but the cost is often built into the quoted rate as a spread. Compare the quote with the current ",["order book","order-book"]," price to see the difference. For small amounts, the convenience may be worth it. For larger trades, a ",["limit order","limit-order"]," on the ",["spot market","spot-trading"]," is often cheaper."],"Convert also helps with pairs that have no direct market, because the exchange routes through other pairs for you. Some exchanges let you convert small leftover balances, often called dust, into a single coin. Limits, supported coins and spreads differ by exchange."],"example":["Suppose the spot order book shows ETH at 3,000 USDT and the Convert screen quotes 2,985 USDT for 1 ETH with zero fee. The spread is 15 USDT, or 0.5%. Selling 2 ETH by Convert gives you 5,970 USDT. Selling on the spot market with a 0.1% ",["taker fee","maker-taker-fees"]," gives about 6,000 minus 6, which is 5,994 USDT, assuming no slippage. The spot trade earns 24 USDT more."],"mistakes":["Assuming zero fee means zero cost when the spread is in the quote.","Using Convert for large trades where a spot limit order would be cheaper.","Waiting too long on the quote screen and getting a refreshed, worse price."],"faq":[{"q":"Is Convert cheaper than spot trading?","a":"Not always. Convert is convenient but often includes a spread. For larger amounts, spot trading with limit orders is usually cheaper."},{"q":"Does Convert have fees?","a":"Many exchanges show no separate fee, but the price you receive can be slightly worse than the market. Compare the quote with the order book."}],"title":"What is Convert on a crypto exchange? Instant swap","description":"How the Convert or instant swap feature works on exchanges, why zero fee does not mean zero cost and when spot trading is cheaper.","related":[["spot-trading","Spot trading","Spot trading is buying or selling a cryptocurrency for immediate delivery at the current market price, so you actually own the coins once the trade is filled."],["market-order","Market order","A market order is an instruction to buy or sell immediately at the best price currently available in the order book, prioritising speed of execution over a specific price."],["bid-ask-spread","Bid-ask spread","The bid-ask spread is the difference between the highest price a buyer is willing to pay (the bid) and the lowest price a seller is willing to accept (the ask) for an asset at a given moment."],["slippage","Slippage","Slippage is the difference between the price you expect when you place a trade and the average price at which the trade actually fills, usually caused by thin liquidity or fast-moving markets."]],"lesson":{"id":"E07","slug":"first-spot-trade","ep":7,"title":"Your first spot trade: from 100 to 0.002 BTC"},"coin":null,"tool":null,"cta":false},"tokenized-stocks":{"slug":"tokenized-stocks","cat":"tokenized-assets","en":"Tokenized stocks","contentLocale":"en","term":"Tokenized stocks","aka":["stock tokens","tokenized equities","xStocks"],"short":"Tokenized stocks are blockchain tokens designed to track the price of a company's shares, usually backed one to one by real shares held by a custodian.","body":["A provider buys real shares, holds them with a regulated custodian and issues tokens that represent them. The tokens can trade on exchanges or move on-chain, sometimes 24 hours a day, even when stock markets are closed. Some products pass on dividends as extra tokens or cash.","Holders usually do not get the same rights as shareholders. You typically cannot vote at company meetings, and your claim is against the issuer and its custodian, not the company itself. Availability depends heavily on the user's country; many products are not offered to US persons or in some other regions.",["Prices can drift from the underlying share when stock markets are closed, because tokens may trade while the reference price is frozen, and ",["liquidity","liquidity"]," is thinner. Compare this with ",["stock perpetuals","stock-perpetuals"],", which give price exposure through derivatives rather than backed tokens."]],"example":"Suppose a tokenized share tracks a stock that closed at 200 USD on Friday. Over the weekend the stock market is closed, but the token trades and climbs to 206 USD, a 3% premium, after positive company news. On Monday the stock opens at 203 USD. If you had bought the token at 206, you would face a 3 USD loss per token once the price realigns with the stock, even though the stock itself rose 1.5%.","mistakes":["Assuming a tokenized stock gives the same voting and legal rights as owning the share.","Ignoring premiums or discounts that appear outside stock market hours.","Not checking who the issuer and custodian are and in which countries the product is allowed."],"faq":[{"q":"Are tokenized stocks real shares?","a":"They are tokens backed by real shares held by a custodian, but you own a claim on the issuer, not the share itself. Rights such as voting usually do not pass through."},{"q":"Can I trade tokenized stocks 24/7?","a":"Many tokenized stocks trade around the clock on crypto platforms, but prices can move away from the stock when its market is closed."}],"title":"What are tokenized stocks? How stock tokens work","description":"How tokenized stocks work, what backs them, what rights holders get and why prices can drift from the real share after hours.","related":[["stock-perpetuals","Stock perpetuals","Stock perpetuals are perpetual futures contracts that track the price of a share or stock index, letting you go long or short with leverage without owning the stock."],["real-world-assets","Real-world assets (RWA)","Real-world assets (RWA) are traditional assets such as bonds, gold, real estate, private credit or stocks represented as tokens on a blockchain."],["spot-bitcoin-etf","Spot bitcoin ETF","A spot bitcoin ETF is an exchange-traded fund that holds actual bitcoin and lets investors gain exposure to its price through a regular brokerage account."],["usdc","USDC","USDC is a US dollar stablecoin issued by Circle, designed to stay at 1 dollar and backed by cash and short-term US government securities, with monthly reserve attestations."]],"lesson":null,"coin":null,"tool":"/topics/tokenized-stocks-vs-perpetuals","cta":true}});
